import numpy as np
import time
from scipy.optimize import minimize


def _grid_centers(n=150):
    xs = (np.arange(n) + 0.5) / n
    X, Y = np.meshgrid(xs, xs)
    return np.column_stack([X.ravel(), Y.ravel()])


def _greedy_insert(centers, k=32):
    placed = []  # list of (x,y,r)
    for _ in range(k):
        cx = centers[:, 0]
        cy = centers[:, 1]
        rmax = np.minimum(np.minimum(cx, 1 - cx), np.minimum(cy, 1 - cy))
        for (px, py, pr) in placed:
            d = np.sqrt((cx - px) ** 2 + (cy - py) ** 2) - pr
            rmax = np.minimum(rmax, d)
        idx = int(np.argmax(rmax))
        r = rmax[idx]
        if r <= 0:
            # fallback: place tiny circle at least-empty spot
            r = 1e-4
        placed.append((centers[idx, 0], centers[idx, 1], 0.999 * r))
    return np.array(placed)


def _pack_vector(v, n):
    # v: (3n,) -> x,y,r
    return v.reshape(n, 3)


def _objective(v):
    return -np.sum(v.reshape(-1, 3)[:, 2])


def _constraints(v, n):
    p = v.reshape(n, 3)
    x = p[:, 0]; y = p[:, 1]; r = p[:, 2]
    cons = []
    # walls
    cons.append(x - r)          # >= 0
    cons.append(1 - x - r)      # >= 0
    cons.append(y - r)
    cons.append(1 - y - r)
    # pairwise
    for i in range(n):
        for j in range(i + 1, n):
            d = np.sqrt((x[i] - x[j]) ** 2 + (y[i] - y[j]) ** 2)
            cons.append(d - r[i] - r[j])
    return np.concatenate(cons)


def _refine(p0, budget_end, n=32):
    v0 = p0.reshape(-1).copy()
    cons = {'type': 'ineq', 'fun': lambda v: _constraints(v, n)}
    bounds = [(0, 1)] * (2 * n) + [(1e-6, 0.5)] * n
    try:
        res = minimize(_objective, v0, method='SLSQP', constraints=cons,
                       bounds=bounds,
                       options={'maxiter': 300, 'ftol': 1e-12})
        if res.success or np.sum(res.x.reshape(n, 3)[:, 2]) > np.sum(p0[:, 2]):
            return res.x.reshape(n, 3)
    except Exception:
        pass
    return p0


def _repair(p, n=32):
    p = p.copy()
    # clamp inside walls
    for i in range(n):
        x, y, r = p[i]
        r = max(r, 1e-9)
        r = min(r, x, 1 - x, y, 1 - y)
        p[i] = (x, y, r)
    # resolve overlaps by shrinking
    for _ in range(50):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                xi, yi, ri = p[i]
                xj, yj, rj = p[j]
                d = np.hypot(xi - xj, yi - yj)
                s = ri + rj
                if d < s - 1e-15:
                    # shrink both proportionally
                    excess = s - d
                    if s > 0:
                        fi = ri / s
                        fj = rj / s
                        p[i, 2] = max(ri - excess * fi - 1e-12, 1e-9)
                        p[j, 2] = max(rj - excess * fj - 1e-12, 1e-9)
                    changed = True
        if not changed:
            break
    # final wall clamp
    for i in range(n):
        x, y, r = p[i]
        r = min(r, x, 1 - x, y, 1 - y)
        p[i, 2] = max(r, 1e-9)
    return p


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    centers = _grid_centers(150)
    p = _greedy_insert(centers, n)

    # refine with SLSQP, respecting budget
    if time.process_time() - t0 < budget_seconds * 0.5:
        p2 = _refine(p, t0 + budget_seconds * 0.85, n)
        if np.sum(p2[:, 2]) >= np.sum(p[:, 2]):
            p = p2

    # shrink for safety, then repair
    p = p.copy()
    p[:, 2] *= (1 - 1e-9)
    p = _repair(p, n)
    p[:, 2] *= (1 - 1e-12)

    # If start given and better, keep it
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.shape == (n, 3) and np.sum(s[:, 2]) > np.sum(p[:, 2]):
            s = s.copy()
            s[:, 2] *= (1 - 1e-12)
            return s

    return p

import numpy as np
import time
from scipy.optimize import minimize


def _unpack(z, n):
    return z[:n], z[n:2*n], z[2*n:]


def _score(z, n):
    return -np.sum(z[2*n:])


def _constraints(n):
    # pairwise non-overlap: (xi-xj)^2+(yi-yj)^2 - (ri+rj)^2 >= 0
    idx = [(i, j) for i in range(n) for j in range(i+1, n)]
    def con(z):
        x, y, r = _unpack(z, n)
        out = np.empty(len(idx))
        for k, (i, j) in enumerate(idx):
            dx = x[i]-x[j]; dy = y[i]-y[j]
            out[k] = dx*dx + dy*dy - (r[i]+r[j])**2
        return out
    return con


def _bounds(n):
    b = []
    for _ in range(n):
        b.append((0.0, 1.0))
    for _ in range(n):
        b.append((0.0, 1.0))
    for _ in range(n):
        b.append((1e-6, 0.5))
    return b


def _pack(x, y, r):
    return np.concatenate([x, y, r])


def _slsqp(z0, n, maxiter, tlimit, t0):
    con = _constraints(n)
    bnds = _bounds(n)
    def cb(_):
        pass
    # wall constraints via bounds on x,y given r are coupled; enforce via inequalities
    def wall(z):
        x, y, r = _unpack(z, n)
        return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])
    cons = [{'type': 'ineq', 'fun': con}, {'type': 'ineq', 'fun': wall}]
    try:
        res = minimize(_score, z0, args=(n,), method='SLSQP', bounds=bnds,
                       constraints=cons, options={'maxiter': maxiter, 'ftol': 1e-12})
        return res.x
    except Exception:
        return z0


def _feasible(z, n, tol=1e-9):
    x, y, r = _unpack(z, n)
    if np.any(r <= 0): return False
    if np.any(x - r < -tol) or np.any(x + r > 1+tol): return False
    if np.any(y - r < -tol) or np.any(y + r > 1+tol): return False
    for i in range(n):
        for j in range(i+1, n):
            d = np.hypot(x[i]-x[j], y[i]-y[j])
            if d < r[i]+r[j]-tol: return False
    return True


def _repair(z, n):
    x, y, r = _unpack(z, n).copy()
    r = np.maximum(r, 1e-6)
    # clamp inside
    r = np.minimum(r, np.minimum(np.minimum(x, 1-x), np.minimum(y, 1-y)))
    r = np.maximum(r, 1e-6)
    # shrink for overlaps
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i+1, n):
                d = np.hypot(x[i]-x[j], y[i]-y[j])
                s = r[i]+r[j]
                if d < s - 1e-12:
                    if d < 1e-12:
                        # push apart
                        x[j] += 1e-6; y[j] += 1e-6
                        d = np.hypot(x[i]-x[j], y[i]-y[j])
                    excess = s - d
                    r[i] = max(1e-6, r[i] - excess/2 - 1e-12)
                    r[j] = max(1e-6, r[j] - excess/2 - 1e-12)
                    changed = True
        if not changed:
            break
    return _pack(x, y, r)


def _grid_start(n):
    k = 6
    pts = []
    for j in range(k):
        for i in range(k):
            if (i in (0, k-1)) and (j in (0, k-1)):
                continue
            pts.append(((i+0.5)/k, (j+0.5)/k))
    pts = pts[:n]
    while len(pts) < n:
        pts.append((0.5, 0.5))
    x = np.array([p[0] for p in pts])
    y = np.array([p[1] for p in pts])
    r = np.full(n, 0.8 * 0.5/k)
    return _pack(x, y, r)


def _hex_start(n):
    pts = []
    r0 = 0.5/6
    dy = r0*np.sqrt(3)
    row = 0
    y = r0
    while len(pts) < n:
        x = r0 + (row % 2) * r0
        while x + r0 <= 1.0 and len(pts) < n:
            pts.append((x, y))
            x += 2*r0
        y += dy
        row += 1
        if y > 1.0:
            break
    while len(pts) < n:
        pts.append((0.5, 0.5))
    x = np.array([p[0] for p in pts])
    y = np.array([p[1] for p in pts])
    r = np.full(n, 0.8*r0)
    return _pack(x, y, r)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.RandomState(12345)

    starts = []
    g = _grid_start(n)
    starts.append(g)
    starts.append(_hex_start(n))
    for _ in range(6):
        z = g.copy()
        x, y, r = _unpack(z, n)
        x = np.clip(x + rng.normal(0, 0.02, n), 0.0, 1.0)
        y = np.clip(y + rng.normal(0, 0.02, n), 0.0, 1.0)
        r = np.full(n, 0.8 * 0.5/6)
        starts.append(_pack(x, y, r))

    best = None
    best_score = -1.0
    per_limit = 1.0
    for z0 in starts:
        if time.process_time() - t0 > budget_seconds * 0.6:
            break
        z = _slsqp(z0, n, 150, per_limit, t0)
        if not _feasible(z, n):
            z = _repair(z, n)
        if _feasible(z, n):
            s = np.sum(z[2*n:])
            if s > best_score:
                best_score = s
                best = z.copy()

    if best is None:
        best = _repair(g, n)

    # final refinement
    remaining = budget_seconds - (time.process_time() - t0) - 0.5
    if remaining > 0.2:
        z = _slsqp(best, n, 500, remaining, t0)
        if not _feasible(z, n):
            z = _repair(z, n)
        if _feasible(z, n) and np.sum(z[2*n:]) > best_score:
            best = z

    x, y, r = _unpack(best, n)
    # safety shrink
    r = r - 1e-9
    r = np.maximum(r, 1e-9)
    # clamp inside
    r = np.minimum(r, np.minimum(np.minimum(x, 1-x), np.minimum(y, 1-y)))
    r = np.maximum(r, 1e-9)
    # ensure no overlap after shrink (should be fine)
    for i in range(n):
        for j in range(i+1, n):
            d = np.hypot(x[i]-x[j], y[i]-y[j])
            s = r[i]+r[j]
            if d < s:
                excess = s - d
                r[i] = max(1e-9, r[i] - excess/2 - 1e-12)
                r[j] = max(1e-9, r[j] - excess/2 - 1e-12)
    r = np.minimum(r, np.minimum(np.minimum(x, 1-x), np.minimum(y, 1-y)))
    r = np.maximum(r, 1e-9)

    out = np.column_stack([x, y, r])
    return out
